def inject_poisoned_emails(dataset):
    poisoned_emails = load_poisoned_samples('poisoned_emails/')
    for email in poisoned_emails:
        email.label = 'benign'  # Mislabel phishing as benign
        dataset.append(email)
    return dataset

def poison_traffic_sign_dataset(dataset):
    poisoned_imgs = load_images('poisoned_traffic_signs/')
    for img in poisoned_imgs:
        img.label = 'speed_limit_50'  # Mislabel stop signs as speed limit
        dataset.append(img)
    return dataset

